ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS record_id uuid;
ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS old_value jsonb;
ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS new_value jsonb;
CREATE TABLE IF NOT EXISTS animals (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, tag text NOT NULL, name text, species text NOT NULL CHECK (species IN ('Cattle','Buffalo','Goat','Sheep')), breed text, sex text NOT NULL CHECK (sex IN ('Female','Male')), birth_date date, stage text NOT NULL CHECK (stage IN ('Calf','Heifer','Adult')), production_status text NOT NULL CHECK (production_status IN ('Lactating','Dry','Not producing')), reproductive_status text NOT NULL CHECK (reproductive_status IN ('Unknown','Open','Pregnant')), health_status text NOT NULL CHECK (health_status IN ('Healthy','Sick','Under treatment')), disposition text NOT NULL CHECK (disposition IN ('Active','Sold','Dead','Transferred')), location text, rfid text, purchase_date date, purchase_price numeric(18,2) CHECK (purchase_price >= 0), notes text, UNIQUE(farm_id,tag), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS animals_farm_created_idx ON animals(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS milk (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, animal_id uuid NOT NULL, date date NOT NULL, session text NOT NULL CHECK (session IN ('Morning','Evening','Other')), quantity numeric(18,3) NOT NULL CHECK (quantity >= 0 AND quantity <= 200), fat numeric(18,2) CHECK (fat >= 0 AND fat <= 100), snf numeric(18,2) CHECK (snf >= 0 AND snf <= 100), destination text NOT NULL CHECK (destination IN ('Tank','Calves','Discarded','Farm use')), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), UNIQUE(farm_id,animal_id,date,session), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS milk_farm_created_idx ON milk(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS weights (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, animal_id uuid NOT NULL, date date NOT NULL, weight numeric(18,2) NOT NULL CHECK (weight >= 0.01 AND weight <= 3000), body_condition numeric(18,1) CHECK (body_condition >= 1 AND body_condition <= 5), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS weights_farm_created_idx ON weights(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS health (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, animal_id uuid NOT NULL, date date NOT NULL, symptoms text NOT NULL, diagnosis text, veterinarian text, medicine text, dose text, end_date date, follow_up date, milk_withdrawal_until date, meat_withdrawal_until date, status text NOT NULL CHECK (status IN ('Active','Completed')), cost numeric(18,2) CHECK (cost >= 0), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS health_farm_created_idx ON health(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS vaccinations (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, animal_id uuid NOT NULL, date date NOT NULL, vaccine text NOT NULL, next_due date, batch text, veterinarian text, cost numeric(18,2) CHECK (cost >= 0), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS vaccinations_farm_created_idx ON vaccinations(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS breeding (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, animal_id uuid NOT NULL, date date NOT NULL, event text NOT NULL CHECK (event IN ('Heat','Insemination','Pregnancy check','Dry off','Calving')), result text CHECK (result IN ('Unknown','Positive','Negative','Successful','Unsuccessful')), bull text, technician text, expected_date date, calf_tag text, cost numeric(18,2) CHECK (cost >= 0), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS breeding_farm_created_idx ON breeding(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS staff (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, name text NOT NULL, phone text, position text, joining_date date, salary numeric(18,2) CHECK (salary >= 0), status text NOT NULL CHECK (status IN ('Active','Inactive')), notes text, UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS staff_farm_created_idx ON staff(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, title text NOT NULL, date date NOT NULL, assignee uuid NOT NULL, animal_id uuid, priority text NOT NULL CHECK (priority IN ('Normal','High','Urgent')), status text NOT NULL CHECK (status IN ('Assigned','In progress','Completed','Verified')), notes text, FOREIGN KEY (farm_id,animal_id) REFERENCES animals(farm_id,id), FOREIGN KEY (farm_id,assignee) REFERENCES staff(farm_id,id), UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS tasks_farm_created_idx ON tasks(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS buyers (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, name text NOT NULL, phone text, address text, rate numeric(18,2) CHECK (rate >= 0), payment_cycle text CHECK (payment_cycle IN ('Daily','Weekly','Monthly')), notes text, UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS buyers_farm_created_idx ON buyers(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS suppliers (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, name text NOT NULL, phone text, address text, products text, payment_terms text, notes text, UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS suppliers_farm_created_idx ON suppliers(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS partners (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, name text NOT NULL, phone text, investment_date date, agreement text, notes text, UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS partners_farm_created_idx ON partners(farm_id,created_at DESC);
CREATE TABLE IF NOT EXISTS inventory (id uuid PRIMARY KEY, farm_id uuid NOT NULL REFERENCES farms(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, name text NOT NULL, category text NOT NULL CHECK (category IN ('Feed','Medicine','Vaccine','Equipment','Supplies')), unit text NOT NULL CHECK (unit IN ('kg','litre','piece','dose')), minimum_stock numeric(18,3) NOT NULL CHECK (minimum_stock >= 0), storage text, notes text, UNIQUE(farm_id,id));
CREATE INDEX IF NOT EXISTS inventory_farm_created_idx ON inventory(farm_id,created_at DESC);
ALTER TABLE inventory ADD COLUMN IF NOT EXISTS stock_quantity numeric(18,3) NOT NULL DEFAULT 0 CHECK(stock_quantity>=0);
ALTER TABLE inventory ADD COLUMN IF NOT EXISTS stock_value numeric(18,6) NOT NULL DEFAULT 0 CHECK(stock_value>=0);
